  ui_story_30540401_80_dialog_content = "<size=45>Hã?</size>",
  ui_story_30540401_81_dialog_content = "Eu queria arrumar antes de você voltar, mas você chegou mais cedo do que eu esperava! Me desculpe muito!",
  ui_story_30540401_82_dialog_content = "Uh, você pode me dizer o que fez...?",
  ui_story_30540401_83_dialog_content = "Arrumei um pouco, desinfetei o quarto com o poder da lanterna e depois passei suas roupas...",
  ui_story_30540401_84_dialog_content = "Então, o que deixou o quarto mais bagunçado?",
