  ui_story_30540401_90_dialog_content = "*Inspirando profundamente e forçando um sorriso*",
  ui_story_30540401_91_dialog_content = "Tudo bem. Você está se esforçando para se desculpar, então eu...",
  ui_story_30540401_92_dialog_content = "Nah, não estou bravo com você.",
  ui_story_30540601_1_dialog_content = "Voltei...",
  ui_story_30540601_2_dialog_content = "\"Eu amo trabalhar, sim, eu amo!\"",
  ui_story_30540601_3_dialog_content = "\"Eu amo trabalhar. E você?\"",
  ui_story_30540601_4_dialog_content = "Por que meus Vagalumes estão cantando uma música tão estranha? Espere... Eles estão... Dançando?!",
  ui_story_30540601_5_dialog_content = "Bem-vindo de volta! Por favor, coloque seu casaco aqui!",
  ui_story_30540601_6_dialog_content = "Ah, e por favor, limpe seus sapatos antes de entrar, se quiser mantê-los nos pés.",
  ui_story_30540601_7_dialog_content = "Vagalumes! Pano de sapato!",
  ui_story_30540601_8_dialog_content = "\"Por favor, use este pano para limpar seus sapatos.\"",
  ui_story_30540601_9_dialog_content = "Oi, você está usando sua roupa nova! Mas, uh... O que exatamente está acontecendo aqui?",
  ui_story_30540601_10_dialog_content = "Estou no meio do <color=#FFB400>trabalho</color>, PlayerName.",
  ui_story_30540601_11_dialog_content = "\"Trabalho\"? Por que vocês continuam falando sobre \"trabalho\"...",
  ui_story_30540601_12_dialog_content = "Bom, na verdade...",
  ui_story_30540601_13_dialog_content = "Um uniforme bem ajustado e bem passado, e uma xícara de café bem quente. Um começo perfeito para um dia duro de trabalho—",
  ui_story_30540601_14_dialog_content = "*Suspiro* Só que... Hoje é meu dia de folga.",
  ui_story_30540601_15_dialog_content = "Está tudo bem, Srta. Nadine?",
  ui_story_30540601_16_dialog_content = "Tudo está perfeitamente bem. É só que eu geralmente estou ocupado no trabalho e me acostumei a estar sempre ocupado.",
  ui_story_30540601_17_dialog_content = "Mas de repente ter um dia de folga sem nada para fazer... Parece um pouco estranho para mim.",
  ui_story_30540601_18_dialog_content = "Você é tão dedicado e esforçado, Nadine! E também ama o seu trabalho!",
  ui_story_30540601_19_dialog_content = "Se ao menos...",
  ui_story_30540601_20_dialog_content = "Hmm? Tem algo em mente, Vice?",
  ui_story_30540601_21_dialog_content = "Ehehe... Eu estava pensando... Se você pudesse me ajudar com algo, eu ficaria muito grato!",
  ui_story_30540601_22_dialog_content = "O que é? Estou sempre disposto a ajudar, desde que esteja dentro da minha capacidade.",
  ui_story_30540601_23_dialog_content = "Sério?",
  ui_story_30540601_24_dialog_content = "Bem, você vê... Acabei de receber um pedido de missão urgente e não tenho escolha a não ser sair imediatamente.",
  ui_story_30540601_25_dialog_content = "Mas hoje é minha vez de fazer a patrulha, e PlayerName ainda não voltou...",
  ui_story_30540601_26_dialog_content = "Então, você poderia me ajudar a gerenciar o Colosso, por favor?",
  ui_story_30540601_27_dialog_content = "Se você tiver alguma dúvida, eu fiz este \"manual de serviço de patrulha\" ao qual você pode se referir sempre que quiser!",
  ui_story_30540601_28_dialog_content = "Entendi... Compreendido. Deixe comigo e fique seguro em sua missão.",
  ui_story_30540601_29_dialog_content = "Você é o melhor! Muito obrigado!",
  ui_story_30540601_30_dialog_content = "Ah, e alguém estará entregando um pacote em breve. Você poderia, por favor, lembrar de recebê-lo?",
  ui_story_30540601_31_dialog_content = "É um envio de roupas novas.",
  ui_story_30540601_32_dialog_content = "Uma delas é uma surpresa para você de PlayerName, então sinta-se à vontade para abrir e dar uma olhada!",
  ui_story_30540601_33_dialog_content = "De qualquer forma, eu preciso ir! A Colossus está em suas mãos agora!",
  ui_story_30540601_34_dialog_content = "Deixe comigo. Farei o meu melhor!",
  ui_story_30540601_35_dialog_content = "Hmm... O manual diz que os Vaga-lumes cuidam da maior parte da limpeza no Colossus. Nesse caso...",
  ui_story_30540601_35X_dialog_content = "Talvez eu devesse tomar uma xícara de café para me animar um pouco?",
  ui_story_30540601_36_dialog_content = "<color=#e8d9bb>Ampliação!</color>",
  ui_story_30540601_38_dialog_content = "Eu não estava prestando atenção quando aquele Firefly passou voando por mim, então eu escorreguei e caí...",
  ui_story_30540601_39_dialog_content = "E derramei café em mim todo. Não tive escolha a não ser trocar para essa roupa.",
  ui_story_30540601_40_dialog_content = "É tão bonito... Juro que não vou sujar este! Mas será que eu posso realmente usá-lo?",
  ui_story_30540601_41_dialog_content = "Claro que pode. Eu estava planejando te dar isso como presente, de qualquer forma.",
  ui_story_30540601_42_dialog_content = "Maravilha!",
  ui_story_30540601_43_dialog_content = "De qualquer forma, o que houve com os Vagalumes? Eles estavam cantando e dançando até agora...",
  ui_story_30540601_44_dialog_content = "Ajustei as configurações de acordo com o manual que o Vice me deixou.",
  ui_story_30540601_45_dialog_content = "O que você acabou de ver foi a formação de espera deles.",
  ui_story_30540601_46_dialog_content = "E aquela música estranha...",
  ui_story_30540601_47_dialog_content = "Eu canto isso para mim o tempo todo. Espero que isso motive nossos amigos a fazerem um trabalho ainda melhor na Colossus!",
  ui_story_30540601_48_dialog_content = "Ah, por que você continua falando em \"trabalho\" e \"empregos\"...",
  ui_story_30540601_49_dialog_content = "Ah, é verdade! Ainda preciso terminar de inspecionar os quartos!",
  ui_story_30540601_50_dialog_content = "\"Inspecionando\"?",
  ui_story_30540601_51_dialog_content = "Oh, donzela!",
  ui_story_30540601_52_dialog_content = "Entendi.",
  ui_story_30540601_53_dialog_content = "Mudando Modos: Varredor.",
  ui_story_30540601_54_dialog_content = "Inspeções de quartos concluídas. O contrabando foi confiscado.",
  ui_story_30540601_55_dialog_content = "C...Contrabando?",
  ui_story_30540601_56_dialog_content = "Isso mesmo! O manual de patrulha do Vice possui várias regras a serem seguidas.",
  ui_story_30540601_57_dialog_content = "\"Para garantir a segurança de todos os passageiros a bordo do Colossus, os seguintes itens não são permitidos a bordo:\"",
  ui_story_30540601_58_dialog_content = "\"Inflamáveis ou explosivos...\"",
  ui_story_30540601_59_dialog_content = "De repente, não consigo deixar de pensar em todas as pessoas que quebram essa regra regularmente.",
  ui_story_30540601_60_dialog_content = "\"Armas perigosas e objetos cortantes...\"",
  ui_story_30540601_61_dialog_content = "Novamente, não consigo deixar de pensar em todas as pessoas que quebram essa regra regularmente também...",
  ui_story_30540601_62_dialog_content = "Viu? Eu só terminei de ler a segunda regra, e você provavelmente já pode citar uma dúzia de infratores!",
  ui_story_30540601_63_dialog_content = "Não há respeito entre as pessoas se não houver respeito pelas regras, sabe?",
  ui_story_30540601_64_dialog_content = "Claro, mas...",
  ui_story_30540601_65_dialog_content = "Donzela! Vamos continuar!",
  ui_story_30540601_66_dialog_content = "Eu deveria te dizer, mesmo o Vice não aplica essas regras muito rigorosamente...",
  ui_story_30540601_66X_dialog_content = "Uh... Olá? Aonde ela foi?",
  ui_story_30540601_67_dialog_content = "<color=#e8d9bb>Dez minutos depois...</color>",
  ui_story_30540601_68_dialog_content = "Onde estão os meus alto-falantes? Alguém os moveu sem a minha permissão?",
  ui_story_30540601_69_dialog_content = "Onde foi parar a minha serra pequena e fofa?",
  ui_story_30540601_70_dialog_content = "O que está fazendo aqui?",
  ui_story_30540601_71_dialog_content = "Regina... Foi você quem pegou minha serra?",
  ui_story_30540601_72_dialog_content = "Sobre o que você está falando? Você é quem roubou minhas caixas de som, não é?",
  ui_story_30540601_73_dialog_content = "Com ciúmes porque eles são ainda mais altos do que você ou algo assim?!",
  ui_story_30540601_74_dialog_content = "Hã? Você quer dizer aqueles alto-falantes ruins usados para atos de abertura? Eu não sonharia em tocá-los nem em um milhão de anos!",
  ui_story_30540601_75_dialog_content = "O que foi isso? Tá tentando arrumar uma briga?!",
  ui_story_30540601_76_dialog_content = "E-Espere vocês dois, acalmem-se! Ambos estão faltando alguns pertences, não é? Será que...",
  ui_story_30540601_77_dialog_content = "Você acha que eu tenho medo de você? Vamos resolver isso de uma vez por todas! Aqui e agora!",
  ui_story_30540601_78_dialog_content = "Você pode ser o juiz, PlayerName!",
  ui_story_30540601_79_dialog_content = "Por que você ainda está lutando?! Eu me recuso a participar disso...!",
  ui_story_30540601_80_dialog_content = "Então permita-me agir como juiz!",
  ui_story_30540601_81_dialog_content = "Eh? Essa voz... Não é...?",
  ui_story_30540601_82_dialog_content = "Primeiro! Seja um farol para guiar os outros adiante!",
  ui_story_30540601_83_dialog_content = "Segundo! Certifique-se de que o uniforme esteja passado e com vincos bem definidos!",
  ui_story_30540601_84_dialog_content = "Terceiro! Mantenha uma ética de trabalho diligente em todos os momentos!",
  ui_story_30540601_85_dialog_content = "\"<color=#FFB400>Capitã da Patrulha</color>\" Nadine está aqui para cumprir seus deveres e presidir esta partida decisiva!",
  ui_story_30540601_86_dialog_content = "... Há tantas coisas erradas nesta situação que nem sei por onde começar!",
  ui_story_30540601_87_dialog_content = "Enfim, você poderia explicar do que se tratava aquela introdução?",
  ui_story_30540601_88_dialog_content = "Bem, uma das regras no manual do Vice é \"preservar um senso de amor e harmonia a bordo da Colossus\"...",
  ui_story_30540601_89_dialog_content = "O que isso tem a ver com a sua introdução maluca de agora?!",
  ui_story_30540601_90_dialog_content = "O manual também afirma que \"ao mediar entre duas partes conflitantes, lembre-se de se apresentar como mediador para ambos os lados.\"",
  ui_story_30540601_91_dialog_content = "Tenho quase certeza de que por \"mediar\", o manual quer dizer \"parar a briga\"...",
  ui_story_30540601_92_dialog_content = "...",
  ui_story_30540601_93_dialog_content = "Olha, PlayerName! Eles estão tão chocados que esqueceram completamente a discussão...",
  ui_story_30540601_94_dialog_content = "Isso deve contar como parar a briga de alguma forma, certo?",
  ui_story_30540601_95_dialog_content = "... De qualquer forma, quando você disse que estava inspecionando os quartos mais cedo...",
  ui_story_30540601_96_dialog_content = "Você por acaso confiscou os alto-falantes de Regina e a serra de Barbara enquanto estava nisso?",
  ui_story_30540601_97_dialog_content = "De fato, eu removi dois alto-falantes grandes do Salão mais cedo.",
  ui_story_30540601_98_dialog_content = "Além de uma serra, que encontrei no canto do Café.",
  ui_story_30540601_99_dialog_content = "E-eu não esqueci lá! Eu só coloquei por um tempinho.",
  ui_story_30540601_100_dialog_content = "Ha? O que te dá o direito de pegar minhas caixas de som?!",
  ui_story_30540601_101_dialog_content = "Os canos estranhos que saem deles soltam chamas! São extremamente perigosos!",
  ui_story_30540601_102_dialog_content = "Mas essas são parte do meu ato! São efeitos especiais!",
  ui_story_30540601_103_dialog_content = "Espere, de acordo com a regra no manual... Seu penteado também é incrivelmente perigoso!",
  ui_story_30540601_104_dialog_content = "Que tipo de regra é essa?!",
  ui_story_30540601_105_dialog_content = "Quando eu embarquei na Colossus pela primeira vez, ninguém mencionou regras pra mim! Por que trazer isso à tona agora, de repente?!",
  ui_story_30540601_106_dialog_content = "P-Por favor, parem de brigar! Enfim...",
  ui_story_30540601_107_dialog_content = "Nadine, você poderia devolver o alto-falante e a serra para eles primeiro, por favor?",
  ui_story_30540601_108_dialog_content = "Mas as regras claramente afirmam...",
  ui_story_30540601_109_dialog_content = "Essas regras nunca foram oficialmente aplicadas na Colossus antes.",
  ui_story_30540601_110_dialog_content = "Isso significa... que eu cometi um erro?",
  ui_story_30540601_111_dialog_content = "De forma alguma! É só que as regras precisam ser ajustadas levemente dependendo da situação. Você não precisa segui-las tão de perto.",
  ui_story_30540601_112_dialog_content = "Muito bem. Afinal, você é o Navegador.",
  ui_story_30540601_113_dialog_content = "Se você diz isso, naturalmente seguirei suas ordens...",
  ui_story_30540601_114_dialog_content = "Então, cadê nossas coisas? Entregue-as e deixaremos tudo isso para trás.",
  ui_story_30540601_115_dialog_content = "Por favor, venha comigo. Eu te levo lá.",
  ui_story_30540601_116_dialog_content = "PlayerName... Eu piorei as coisas, não foi?",
  ui_story_30540601_117_dialog_content = "*Ahem* Não se martirize por isso.",
  ui_story_30540601_118_dialog_content = "Seguir as regras de maneira tão próxima e fiel como você fez também é digno de elogios.",
  ui_story_30540601_119_dialog_content = "As coisas apenas saíram um pouco do controle, só isso.",
  ui_story_30540601_120_dialog_content = "Sem dúvida, acho que devemos evitar confiscar as coisas de alguém a partir de agora.",
  ui_story_30540601_121_dialog_content = "Todos a bordo do Colossus se preocupam uns com os outros e nunca fariam nada para colocar em perigo a vida de alguém, relativamente...",
  ui_story_30540601_122_dialog_content = "Muito bem, entendi agora!",
  ui_story_30540601_123_dialog_content = "Ah! Tenho certeza de que você deve estar com sede depois de toda essa explicação.",
  ui_story_30540601_124_dialog_content = "Gostaria de algo para beber? Posso fazer a maioria das coisas, especialmente chá e café.",
  ui_story_30540601_125_dialog_content = "Não, obrigado, estou bem.",
  ui_story_30540601_125X1_dialog_content = "Mas sinto que preciso fazer algo como um pedido de desculpas... Gostaria de uma massagem nos ombros então?",
  ui_story_30540601_126_dialog_content = "Ah... T-Talvez uma xícara de café não seja má ideia... Com leite extra e açúcar, por favor!",
  ui_story_30540601_127_dialog_content = "Sem problemas! Estarei de volta com seu café antes que você perceba!",
  ui_story_30540601_128_dialog_content = "Voltei, PlayerName—",
  ui_story_30540601_129_dialog_content = "\"Eu amo trabalhar, sim, eu amo!\"",
  ui_story_30540601_130_dialog_content = "Ahhh!!",
  ui_story_30540601_131_dialog_content = "N-Nadine, você está bem?!",
  ui_story_30540601_132_dialog_content = "Eu... estou bem... Mas o seu café, eu...",
  ui_story_30540601_133_dialog_content = "Isso não é importante! Você está sentindo dor em algum lugar?",
  ui_story_30540601_134_dialog_content = "Não, mas... Minhas roupas novas...",
  ui_story_30540601_135_dialog_content = "Desculpe! Vou lavá-los agora mesmo!",
  ui_story_30540601_136_dialog_content = "Tudo bem, só pegou em uma parte pequena... *Suspiro* Ela já se foi.",
  ui_story_30540601_137_dialog_content = "Ugh...",
  ui_story_30540601_138_dialog_content = "Tudo bem, Nadine. O café só derramou em uma pequena parte das roupas.",
  ui_story_30540601_139_dialog_content = "Mas... Mas eu prometi que não ia sujar esse!",
  ui_story_30540601_140_dialog_content = "E eu também falhei completamente no <color=#FFB400>dever de patrulha</color>...",
  ui_story_30540601_141_dialog_content = "Foram apenas pequenos erros, Nadine! É perfeitamente normal encontrar pequenos problemas como este.",
  ui_story_30540601_142_dialog_content = "Além disso, ver você cair e derramar bebidas em si mesmo... Eu já me acostumei, pelo menos.",
  ui_story_30540601_143_dialog_content = "Hã?! E-Eu sou... Realmente tão desajeitado assim...?",
  ui_story_30540601_144_dialog_content = "Não é isso que eu quis dizer! O que eu quero dizer é que sua desajeitada ocasional é um dos seus traços adoráveis!",
  ui_story_30540601_145_dialog_content = "De qualquer forma, você não precisa se preocupar com isso.",
  ui_story_30540601_146_dialog_content = "Quanto mais você tenta me consolar... Mais eu sinto que estou decepcionando todo mundo.",
  ui_story_30540601_147_dialog_content = "Mas por quê? São apenas suas roupas, afinal! A menos que... É isso que está te incomodando? Sujar suas roupas?",
  ui_story_30540601_148_dialog_content = "Sim... Um uniforme é extremamente importante.",
  ui_story_30540601_149_dialog_content = "Para todos me darem um uniforme tão bonito... Eles devem estar esperando que eu faça um trabalho ainda melhor do que antes.",
  ui_story_30540601_150_dialog_content = "De jeito nenhum! Por que você pensaria isso?",
  ui_story_30540601_151_dialog_content = "Força do hábito, eu suponho...",
  ui_story_30540601_152_dialog_content = "*Suspiro* Você está sempre falando de trabalho, mesmo quando não está no trabalho...",
  ui_story_30540601_153_dialog_content = "O motivo pelo qual te dei essas roupas foi porque achei que elas realmente combinavam com você, só isso!",
  ui_story_30540601_154_dialog_content = "Além disso, eu pensei que, ao te dar roupas mais casuais e confortáveis...",
  ui_story_30540601_155_dialog_content = "Você seria capaz de <color=#FFB400>se afastar do trabalho e descansar</color> um pouco mais.",
  ui_story_30540601_156_dialog_content = "Eu não achei que você levaria o dever de patrulha tão a sério quanto o seu próprio trabalho.",
  ui_story_30540601_157_dialog_content = "Entendi. Mas essa roupa... É casual?",
  ui_story_30540601_158_dialog_content = "Uh... Ok, você me pegou. Eu também não tenho certeza disso...",
  ui_story_30540601_159_dialog_content = "Mas olha! É leve e respirável, e não tem nenhuma propriedade defensiva.",
  ui_story_30540601_160_dialog_content = "Parece um pouco mais relaxado do que seu uniforme habitual, certo?",
  ui_story_30540601_161_dialog_content = "Eu acho que sim...",
  ui_story_30540601_162_dialog_content = "De qualquer forma, é ótimo que você seja tão dedicado em tudo que faz, mas isso também pode lhe causar muito estresse desnecessário.",
  ui_story_30540601_163_dialog_content = "Estar de plantão é trabalho, não me entenda mal, mas desde que você faça o check-in regularmente e complete as patrulhas no horário, isso é suficiente.",
  ui_story_30540601_164_dialog_content = "Não há necessidade de levar isso tão a sério.",
  ui_story_30540601_165_dialog_content = "Agora que estou de volta e não tenho nada para fazer, por que não te mostro como lidar com o dever de patrulha do jeito certo?",
  ui_story_30540601_166_dialog_content = "Beleza!",
  ui_story_30540601_167_dialog_content = "Estou de volta! Aconteceu alguma coisa enquanto eu estava fora, Nadine...?",
  ui_story_30540601_168_dialog_content = "\"Eu amo intervalos, sim, eu amo!\"",
  ui_story_30540601_169_dialog_content = "\"Eu amo pausas, e você?\"",
  ui_story_30540601_170_dialog_content = "Por que os Vagalumes estão cantando uma música tão estranha? Espere... Eles estão dançando?!",
  ui_story_30540601_171_dialog_content = "Bem-vinda de volta, Senhorita Vice!",
  ui_story_30540601_172_dialog_content = "Já que Vice perguntou tão sinceramente...",
  ui_story_30540601_173_dialog_content = "Responderemos o mais sinceramente possível!",
  ui_story_30540601_174_dialog_content = "Estamos em serviço de patrulha.",
  ui_story_30540601_175_dialog_content = "E já que estamos em serviço de patrulha...",
  ui_story_30540601_176_dialog_content = "Para manter um ambiente pacífico e amoroso a bordo da Colossus...",
  ui_story_30540601_177_dialog_content = "Reprogramamos os Vaga-lumes para tocar uma nova música!",
  ui_story_30540601_178_dialog_content = "Uma que ajudará todos a desfrutar de uma sensação de relaxamento!",
  ui_story_30540601_179_dialog_content = "Vamos fazer o nosso melhor para relaxar!",
  ui_story_30540601_180_dialog_content = "<color=#e8d9bb>Ampliação!</color>",
  ui_story_30540601_181_dialog_content = "... Há tantas coisas erradas nesta situação que nem sei por onde começar!",
  ui_story_30540602_1_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_30540602_2_dialog_content = "Ahhh—Minha lanterna foi levada pelo vento!",
  ui_story_30540602_3_dialog_content = "Cara, se ao menos eu não tivesse ouvido aquele mascate! O que eu estou fazendo aqui, mexendo nessas poças de maré?",
  ui_story_30540602_4_dialog_content = "...",
  ui_story_30540602_5_dialog_content = "Ei, vejo uma luz ali! Melhor irmos dar uma olhada.",
  ui_story_30540602_6_dialog_content = "...",
  ui_story_30540602_7_dialog_content = "Espere, algo naquela garota segurando uma lanterna parece estranhamente familiar.",
  ui_story_30540602_8_dialog_content = "É Nadine! O que você está fazendo aqui?",
  ui_story_30540602_9_dialog_content = "Navegador! Espere, não deveria estar fazendo a mesma pergunta para você?",
  ui_story_30540602_10_dialog_content = "Antes disso, você deve saber—",
  ui_story_30540602_11_dialog_content = "O vento e as ondas aqui são realmente fortes, e não há muitos lugares seguros para encontrar apoio.",
  ui_story_30540602_12_dialog_content = "Um passo em falso e você pode acabar no oceano. Você deve voltar o mais rápido possível.",
  ui_story_30540602_13_dialog_content = "Eu sei, eu sei. Você é tão responsável quanto sempre, Nadine.",
  ui_story_30540602_14_dialog_content = "Eu só nunca esperava encontrar você em Twin Pavilions Bay, só isso...",
  ui_story_30540602_15_dialog_content = "E você parece um pouco diferente do normal...",
  ui_story_30540602_16_dialog_content = "Você pode me dizer o que está fazendo aqui?",
  ui_story_30540602_17_dialog_content = "Você realmente é persistente.",
  ui_story_30540602_18_dialog_content = "... Eu acho que posso te contar sobre meu trabalho de meio período - um segurador de lanterna.",
  ui_story_30540602_19_dialog_content = "O aspecto mais importante do meu trabalho é... esperar.",
  ui_story_30540602_20_dialog_content = "Esperando?",
  ui_story_30540602_21_dialog_content = "Sim. Você vê o horizonte ali? Provavelmente está muito escuro para ver claramente agora.",
  ui_story_30540602_22_dialog_content = "Mas geralmente há muitos navios por lá. Muitos mesmo.",
  ui_story_30540602_23_dialog_content = "Navios mercantes viajando para o norte e sul, embarcações de pesca transportando grandes capturas e barcos de turismo levando passageiros animados.",
  ui_story_30540602_24_dialog_content = "Meu colega do turno anterior disse que os visitantes costumam recitar poemas enquanto apreciam as vistas daqui.",
  ui_story_30540602_25_dialog_content = "Deve ser muito reconfortante para a mente e o espírito.",
  ui_story_30540602_26_dialog_content = "Então, você está esperando por esses navios?",
  ui_story_30540602_27_dialog_content = "Sim. Meu trabalho é aguardar o retorno de todos os navios que partem daqui.",
  ui_story_30540602_28_dialog_content = "E quando o tempo está especialmente ruim, também é meu trabalho iluminar o caminho deles para a segurança!",
  ui_story_30540602_29_dialog_content = "O que é ainda mais um motivo para você voltar agora, Navegador. É perigoso estar fora e a descoberto neste clima.",
  ui_story_30540602_30_dialog_content = "Talvez até esteja se formando uma tempestade...",
  ui_story_30540602_31_dialog_content = "Por que você não vem comigo, Nadine? Se o tempo está tão ruim assim, provavelmente você também não deveria estar trabalhando.",
  ui_story_30540602_32_dialog_content = "Não posso sair. Ainda não.",
  ui_story_30540602_33_dialog_content = "Ainda estou esperando por algo...",
  ui_story_30540602_34_dialog_content = "Esperando pelo quê?",
  ui_story_30540602_35_dialog_content = "Pelos sons daqueles navios retornando ao porto.",
  ui_story_30540602_36_dialog_content = "... Você já viveu algo assim, Navegador?",
  ui_story_30540602_37_dialog_content = "Quando você passa um dia inteiro em um estado completo de foco, começa a perceber todos os tipos de sons.",
  ui_story_30540602_38_dialog_content = "Gosta de ouvir os pássaros voando entre as nuvens?",
  ui_story_30540602_39_dialog_content = "Sim, algo assim.",
  ui_story_30540602_40_dialog_content = "Quando trabalho neste recife, observando todos esses barcos indo e vindo...",
  ui_story_30540602_41_dialog_content = "As ondas trazem-me histórias dos navios no mar.",
  ui_story_30540602_42_dialog_content = "Isso é bem incomum...",
  ui_story_30540602_43_dialog_content = "Uma vez, ouvi falar de como um barco de pesca virou e sua tripulação foi jogada ao mar.",
  ui_story_30540602_44_dialog_content = "Felizmente, um barco de resgate próximo apareceu e tirou todos da água.",
  ui_story_30540602_45_dialog_content = "Quando os pescadores finalmente chegaram à praia, suas esposas reagiram das mais diversas maneiras.",
  ui_story_30540602_46_dialog_content = "Algumas delas abraçaram seus maridos e choraram, enquanto outras os arrastaram para casa puxando pela orelha.",
  ui_story_30540602_47_dialog_content = "Entendi... Histórias assim são como nuvens: elas vêm em todas as formas e tamanhos.",
  ui_story_30540602_48_dialog_content = "Eles podem te contar muito sobre o mundo ao nosso redor e o quão rápido as coisas podem mudar.",
  ui_story_30540602_49_dialog_content = "De fato... Bem, o vento está ficando mais forte. Deve estar acontecendo uma tempestade violenta agora.",
  ui_story_30540602_50_dialog_content = "Tem certeza de que não quer voltar? Ainda há tempo, sabe...",
  ui_story_30540602_51_dialog_content = "Eu vou ficar bem. Conte-me outra história que você ouviu do mar!",
  ui_story_30540602_52_dialog_content = "Isso nos ajudará a passar o tempo!",
  ui_story_30540602_53_dialog_content = "As histórias do oceano são praticamente todas iguais. Eu não acho que as pessoas realmente se importariam em ouvi-las.",
  ui_story_30540602_54_dialog_content = "Por que eu não te conto uma história que me foi contada por outra pessoa? Meu colega, para ser mais preciso.",
  ui_story_30540602_55_dialog_content = "Nas margens de uma terra distante, há uma torre de pedra em forma de lótus.",
  ui_story_30540602_56_dialog_content = "Aos pés desta torre, há inúmeros pequenos leões, também feitos de pedra.",
  ui_story_30540602_57_dialog_content = "Esta torre distante não é particularmente alta ou bonita. Também não emite nenhum brilho dourado.",
  ui_story_30540602_58_dialog_content = "No entanto, ocupa um lugar especial nos corações daqueles que moram por perto. Sempre que sofre danos, alguém inevitavelmente o consertará.",
  ui_story_30540602_59_dialog_content = "Até hoje, ela se mantém orgulhosa à beira do mar. Ao longo dos anos, pessoas ficaram no topo da torre com lanternas nas mãos, assim como eu...",
  ui_story_30540602_60_dialog_content = "Guiando navios desgarrados para a segurança por inúmeros séculos.",
  ui_story_30540602_61_dialog_content = "... Sempre gostei dessa história, principalmente porque também carrego uma lanterna por onde vou.",
  ui_story_30540602_62_dialog_content = "Quero continuar iluminando o caminho para os outros, mesmo que seja por um pouco mais de tempo.",
  ui_story_30540602_63_dialog_content = "... O vento está piorando ainda mais, Navegador... Você conseguirá se manter de pé?",
  ui_story_30540602_64_dialog_content = "Eu vou ficar bem.",
  ui_story_30540602_65_dialog_content = "Então eu sugiro que você encontre um lugar melhor para se apoiar. Quando a chuva começar a cair, talvez eu não consiga te salvar.",
  ui_story_30540602_66_dialog_content = "Não se preocupe, vou pensar em algo se as coisas realmente piorarem.",
  ui_story_30540602_67_dialog_content = "Se você já terminou sua história, gostaria de compartilhar uma minha.",
  ui_story_30540602_68_dialog_content = "Uma vez, havia um viajante que chegou às margens da Baía dos Pavilhões Gêmeos. Enquanto observava as poças de maré, ele conheceu uma jovem garota de Lumópolis.",
  ui_story_30540602_69_dialog_content = "Ela estava vestida à moda de Twin Pavilions Bay. Enquanto caminhava pela orla, segurava um lampião nas mãos.",
  ui_story_30540602_70_dialog_content = "Uma tempestade estava chegando, mas ela se recusou a deixar seu posto no topo de um enorme recife.",
  ui_story_30540602_71_dialog_content = "Ela ouvia as ondas enquanto esperava os navios voltarem para casa.",
  ui_story_30540602_72_dialog_content = "Não havia faróis aqui, tornando os deveres dela especialmente importantes diante da tempestade que se aproximava - uma protetora que ela é.",
  ui_story_30540602_73_dialog_content = "Ela não estava apenas protegendo os navios no mar, mas também qualquer pessoa perdida que aparecesse na praia!",
  ui_story_30540602_74_dialog_content = "Você está...",
  ui_story_30540602_75_dialog_content = "Você está me elogiando agora?",
  ui_story_30540602_76_dialog_content = "Acho que ninguém nunca reconheceu meu trabalho assim!",
  ui_story_30540602_77_dialog_content = "Tenho certeza de que todos sentem isso sobre seu trabalho, mesmo que não digam.",
  ui_story_30540602_78_dialog_content = "Ouvindo os barcos indo e vindo e iluminando o caminho de volta para casa...",
  ui_story_30540602_79_dialog_content = "Você é tão importante quanto um farol aos olhos deles!",
  ui_story_30540602_80_dialog_content = "A chuva está começando a cair.",
  ui_story_30540602_81_dialog_content = "Você tem certeza absoluta de que não quer voltar, Navegador?",
  ui_story_30540602_82_option_content = "Você realmente precisa perguntar?",
  ui_story_30540602_83_option_content = "Não posso deixar o farol desassistido, posso?",
  ui_story_30540602_84_dialog_content = "Navegador... Obrigado.",
  ui_story_30540602_85_dialog_content = "Quero tentar algo.",
  ui_story_30540602_86_dialog_content = "Usar meu poder para ajudar o máximo de pessoas possível, mesmo que seja apenas um único banhista perdido!",
  ui_story_30540602_87_dialog_content = "Luz... reúna-se agora.",
  ui_story_30540602_88_dialog_content = "Sob a lanterna!",
  ui_story_30540602_89_dialog_content = "Os céus estão clareando.",
  ui_story_30540602_90_dialog_content = "Atchim! Ugh, acho que posso ter pegado um resfriado.",
  ui_story_30540602_91_dialog_content = "Faz sentido, já que ficamos tanto tempo na chuva forte.",
  ui_story_30540602_92_dialog_content = "Ainda assim, devemos ter ajudado algumas pessoas que estavam perdidas no mar, certo?",
  ui_story_30540602_93_dialog_content = "Tenho certeza de que sim. Afinal, o mar parece muito menos triste agora.",
  ui_story_30540602_94_dialog_content = "O mar está vivo. Isso é algo que sempre vou lembrar quando ele parecer triste.",
  ui_story_30540602_95_dialog_content = "É por isso que quero erguer minha lanterna ainda mais alto. Tão alto quanto um farol.",
  ui_story_30540602_96_dialog_content = "Você consegue, Nadine! Então, podemos voltar agora?",
  ui_story_30540602_97_dialog_content = "Sim. Assim que voltarmos para a cidade, vou colocar roupas secas e tirar uma bela e longa soneca...",
  ui_story_30540602_98_dialog_content = "Espere! Ainda tenho que aparecer no trabalho hoje!",
  ui_story_30540602_99_dialog_content = "Ah não, que horas são...?",
  ui_story_30540602_100_dialog_content = "Hã? Você quer dizer que está fazendo isso além do seu trabalho habitual em Lumópolis?!",
  ui_story_30540602_101_dialog_content = "Isso é demais, até mesmo para você! Você deveria ligar doente!",
  ui_story_30540602_102_dialog_content = "E-eu não posso! Trabalho é trabalho. Faltar seria o mesmo que negligenciar minhas responsabilidades! Eu tenho que... Atchim!",
  ui_story_30540602_103_dialog_content = "Atchim! Atchim! Atchim!",
  ui_story_30540602_104_dialog_content = "Volte e descanse agora mesmo, Nadine!",
  ui_story_30540602_105_dialog_content = "Mas meu trabalho...",
  ui_story_30540602_106_dialog_content = "Atchim!"
}
return config
